C=np.array([[lo[j] if c[j]==0 else hi[j] for j in range(5)] for c in itertools.product([0,1],repeat=5)])
X=np.vstack([X,C])
def pre(x):
    h1=x.T;h2=x.T;out=[]
    for k in range(6):
        W1,b1=A[k];W2,b2=B[k]; p1=W1@h1+b1[:,None]; p2=W2@h2+b2[:,None]; out.append((p1,p2,p1-p2))
        h1=np.maximum(p1,0);h2=np.maximum(p2,0)
    return out
P=pre(X)
res={}
for k in [2,3,4,5]:
    ext=[]
    for t in range(3):
        v=P[k][t]; mn=v.min(1).copy(); mx=v.max(1).copy()
        # refine via local opt from best samples
        for i in range(50):
            for sgn,arr in [(1,mn),(-1,mx)]:
                x0=X[np.argmin(sgn*v[i])]
                r=minimize(lambda x: sgn*pre(x[None])[k][t][i,0], x0, bounds=list(zip(lo,hi)), method='L-BFGS-B')
