                else: arr[i]=max(arr[i],val)
        ext.append((mn,mx))
    res[k]=ext
import pickle; pickle.dump(res,open('ext.pkl','wb'))
for k in res:
    print(k, [ (np.median(e[1]-e[0])) for e in res[k]])
